head.script:
scwin.trigger1_onclick = function(e) {
    count++;
    widgetContainer1.addWidgets({
        id: "widget" + count,
        title: "위젯" + count,
        src: "widgetContainer_onwidgetmov_WPF-1488_(WSQ-2470)_sub.xml",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 200,
        unitHeight: 225
    });
};
scwin.widgetContainer1_onwidgetmove = function(id, newRect, oldRect) {
    var logStr = "onwidgetmove [" + id + "]\n";
    logStr += "newPos [x=" + newRect.x + ", y=" + newRect.y + ", unitWidth=" + newRect.unitWidth + ", unitHeight=" + newRect.unitHeight + "]\n";
    logStr += "oldPos [x=" + oldRect.x + ", y=" + oldRect.y + ", unitWidth=" + oldRect.unitWidth + ", unitHeight=" + oldRect.unitHeight + "]\n";
    WebSquare.logger.printLog(logStr);
    textarea1.setValue(textarea1.getValue() + "\n" + logStr);
}
scwin.widgetContainer1_onwidgetresize = function(id, newRect, oldRect) {
    var logStr = "onwidgetresize [" + id + "]\n";
    logStr += "newPos [x=" + newRect.x + ", y=" + newRect.y + ", unitWidth=" + newRect.unitWidth + ", unitHeight=" + newRect.unitHeight + "]\n";
    logStr += "oldPos [x=" + oldRect.x + ", y=" + oldRect.y + ", unitWidth=" + oldRect.unitWidth + ", unitHeight=" + oldRect.unitHeight + "]\n";
    WebSquare.logger.printLog(logStr);
    textarea1.setValue(textarea1.getValue() + "\n" + logStr);
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.count = 0;
    scwin.trigger1_onclick();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
